using SteamEngine.Common;

namespace SteamEngine.CompiledScripts {

	/// <summary>#962 - a spell's live cast time, mana, duration and skill on Erebor, generated by the converter into
	/// systems/spellvalues.def. Those beat what the spell's own section says.</summary>
	public class SpellValuesDef : AbstractDef {
		private string spell, castTime, mana, duration, skill;

		public SpellValuesDef(string defname, string filename, int headerLine)
			: base(defname, filename, headerLine) {
		}

		public override void LoadScriptLines(PropsSection ps) {
			foreach (PropsLine prop in ps.PropsLines) {
				switch (prop.Name.ToLowerInvariant()) {
					case "spell":
						this.spell = prop.Value;
						break;
					case "casttime":
						this.castTime = prop.Value;
						break;
					case "mana":
						this.mana = prop.Value;
						break;
					case "duration":
						this.duration = prop.Value;
						break;
					case "skill":
						this.skill = prop.Value;
						break;
				}
			}
		}

		protected override void On_AfterLoadFromScripts() {
			base.On_AfterLoadFromScripts();
			SpellDef def = SpellDef.GetByDefname(this.spell) as SpellDef;
			if (def == null) {
				Logger.WriteWarning(this.Filename, this.HeaderLine, "Values for " + this.spell + ", which doesn't exist.");
			} else {
				def.SetLiveValues(this.Filename, this.HeaderLine, this.castTime, this.mana, this.duration, this.skill);
			}
		}
	}
}
